// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/MANU.sol";

contract MANUFeeDistributionTest is Test {
    MANU token;
    address owner = address(this);
    address alice = address(0x1);
    address bob = address(0x2);
    address charlie = address(0x3);
    address marketingAddr;

    function setUp() public {
        // Deploy token
        token = new MANU();

        // Set test marketing address
        marketingAddr = address(0x4);
        // Note: Requires modification to marketing_address visibility for testing
        vm.store(
            address(token),
            bytes32(uint256(keccak256("MANU.marketing_address"))),
            bytes32(uint256(uint160(marketingAddr)))
        );

        // Exclude owner from fee to avoid fees during setup
        token.excludeFromFee(owner);

        // Fund test accounts
        token.transfer(alice, 1000 ether);
        token.transfer(charlie, 500 ether);

        // Simulate adding addresses to system by performing transactions
        vm.prank(charlie);
        token.transfer(address(0x5), 1);
    }

    function testSupplyInconsistency() public {
        // Initial balances
        uint256 initialSupply = token.totalSupply();
        uint256 initialContractBalance = token.balanceOf(address(token));
        uint256 initialMarketingBalance = token.balanceOf(marketingAddr);

        // Record balances of participants
        uint256 initialAlice = token.balanceOf(alice);
        uint256 initialCharlie = token.balanceOf(charlie);

        // Perform transfer to trigger fee logic
        uint256 transferAmount = 100 ether;
        vm.prank(alice);
        token.transfer(bob, transferAmount);

        // Post-transfer metrics
        uint256 finalSupply = token.totalSupply();
        uint256 marketingIncrease = token.balanceOf(marketingAddr) - initialMarketingBalance;
        uint256 charlieIncrease = token.balanceOf(charlie) - initialCharlie;
        uint256 contractIncrease = token.balanceOf(address(token)) - initialContractBalance;

        // Total "fee" distributions (should only equal burned amount)
        uint256 totalDistributed = marketingIncrease + charlieIncrease + contractIncrease;

        // Consistency checks
        assertGt(
            totalDistributed,
            initialSupply - finalSupply,
            "Total distribution exceeds supply reduction - critical fee allocation issue"
        );
        assertGt(
            charlieIncrease,
            0,
            "Reward account should receive tokens"
        );
    }
}
